<?php
/** Plugin Name: TEMP PS S1721r: pakuociu seimu priskyrimas is xlsx (500 eil., 228 seimos; sausas+konservai, be raudonu). 1 dry, 2 rasyti (bak opcija ps_s1721_priskyrimas_bak), 3 patikra, 9 atstatyti */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1721r'])) return; $f=$_GET['ps_s1721r']; $r=['v'=>'S1721r','faze'=>$f]; @set_time_limit(170); global $wpdb;
  $D=json_decode(base64_decode(''),true); $META='_ps_dydzio_seima'; $BAK='ps_s1721_priskyrimas_bak';
  $trans=function() use ($wpdb){ foreach(['ps_dk_seimos','ps_dydz_auto_bazes'] as $t) delete_transient($t); $wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE '_transient_ps_dydz_pard%' OR option_name LIKE '_transient_timeout_ps_dydz_pard%' OR option_name LIKE '_transient_ps_dk_%' OR option_name LIKE '_transient_timeout_ps_dk_%'"); };
  try{
  $r['eil']=count($D); $seimos=[]; foreach($D as $x) $seimos[$x['seima']][]=$x['id']; $r['seimos']=count($seimos);
  if($f==='1'||$f==='2'){
    $st=['nera_prekes'=>[],'ne_publish'=>[],'jau_ta_pati'=>0,'jau_kita'=>[],'be_termino'=>[],'rasyti'=>0]; $plan=[];
    foreach($D as $x){ $id=(int)$x['id']; $p=get_post($id); if(!$p||$p->post_type!=='product'){ $st['nera_prekes'][]=$id; continue; } if($p->post_status!=='publish') $st['ne_publish'][]=[$id,$p->post_status];
      $sena=(string)get_post_meta($id,$META,true);
      if($sena===$x['seima']){ $st['jau_ta_pati']++; } elseif($sena!==''){ $st['jau_kita'][]=[$id,$sena,$x['seima']]; } else { $plan[]=[$id,$x['seima']]; }
      $t=wp_get_object_terms($id,'pa_pakuotes_dydis',['fields'=>'names']); if(!is_wp_error($t)&&!$t) $st['be_termino'][]=[$id,$x['dydis']];
    }
    $st['rasyti']=count($plan); $r['dry']=$st;
    // seimos, kur dalis nariu jau turi kita rakta (pilotas) — visai seimai naudosim ESAMA rakta, kad nesuskiltu
    $perrasyk=[]; foreach($st['jau_kita'] as $j){ $perrasyk[$j[2]]=$j[1]; } $r['seimos_su_esamu_raktu']=$perrasyk;
    if($f==='2'){
      if($st['nera_prekes']) throw new Exception('yra neegzistuojanciu prekiu');
      $bak=get_option($BAK); if(!is_array($bak)) $bak=[]; $n=0; $term=0; $termErr=[];
      foreach($plan as $pl){ $id=$pl[0]; $seima=$perrasyk[$pl[1]]??$pl[1]; if(!array_key_exists((string)$id,$bak)) $bak[(string)$id]=(string)get_post_meta($id,$META,true); update_post_meta($id,$META,$seima); $n++; }
      foreach($st['be_termino'] as $bt){ if(taxonomy_exists('pa_pakuotes_dydis')&&$bt[1]!==''){ $res=wp_set_object_terms($bt[0],(string)$bt[1],'pa_pakuotes_dydis',true); if(is_wp_error($res)) $termErr[]=[$bt[0],$res->get_error_message()]; else { $term++; if(!isset($bak['_term_'.$bt[0]])) $bak['_term_'.$bt[0]]=(string)$bt[1]; } } }
      update_option($BAK,$bak,false); $r['irasyta']=$n; $r['terminai_prideti']=$term; $r['terminai_klaidos']=$termErr; $r['bak_irasu']=count($bak);
      $trans(); if(function_exists('wp_cache_clear_cache')){ wp_cache_clear_cache(); $r['supercache']='isvalytas'; }
    }
  }
  if($f==='3'){
    $r['meta_viso']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->postmeta} m JOIN {$wpdb->posts} p ON p.ID=m.post_id AND p.post_status='publish' WHERE m.meta_key='$META' AND m.meta_value<>''");
    $r['seimos_db']=(int)$wpdb->get_var("SELECT COUNT(DISTINCT meta_value) FROM {$wpdb->postmeta} WHERE meta_key='$META' AND meta_value<>''");
    $r['katalogo_seimos']=class_exists('Petshop_Dydziu_Katalogas')?count(Petshop_Dydziu_Katalogas::seimos()):'-';
    $r['bak_irasu']=count((array)get_option($BAK));
    foreach(['josera-lamb-rice-eriena-ryziais','josera-mini-lamb-begrudis-mazu-veisliu'] as $s){ if(!isset($seimos[$s])) continue; $r['pvz'][$s]=array_map(function($x){ return [$x['id'],$x['uzr'],$x['yra']?'yra':'NERA',$x['pard'],round($x['perkg'],2),$x['sutaupai'].'%',$x['geriausia']?'best':'',$x['perkamiausias']?'top':'']; },Petshop_Dydziai::eilutes($s,$seimos[$s][0])); }
    $ua=['timeout'=>25,'sslverify'=>false,'user-agent'=>'Mozilla/5.0 ps-s1721','cookies'=>['ps_js'=>'1']];
    foreach(['josera'=>'/gamintojas/josera/','farmina'=>'/gamintojas/farmina/','sausas_sunims'=>'/kategorija/sunims/maistas-sunims/sausas-maistas-sunims/','konservai_katems'=>'/kategorija/katems/maistas-katems/konservai-katems/'] as $k=>$u){ $rs=wp_remote_get(home_url($u).'?ps_nocache='.time(),$ua); $h=wp_remote_retrieve_body($rs); $r['http'][$k]=['code'=>wp_remote_retrieve_response_code($rs),'korteliu'=>preg_match_all('/class="product-small col[^"]*\bpost-\d+/',$h),'ps_dk'=>substr_count($h,'class="ps-dk"'),'rezultatu'=>(preg_match('/(\d+)\s*(rezultat|prekė|prekės|prekių)/u',$h,$m)?$m[0]:'')]; }
    $lf=ini_get('error_log'); if($lf&&is_file($lf)){ $sz=filesize($lf); $h2=fopen($lf,'r'); fseek($h2,max(0,$sz-2500)); $r['log_uodega']=array_slice(array_filter(explode("\n",stream_get_contents($h2))),-3); fclose($h2); }
  }
  if($f==='9'){ $bak=get_option($BAK); $n=0; $t=0; foreach((array)$bak as $k=>$v){ if(strpos($k,'_term_')===0){ wp_remove_object_terms((int)substr($k,6),(string)$v,'pa_pakuotes_dydis'); $t++; } else { if($v==='') delete_post_meta((int)$k,$META); else update_post_meta((int)$k,$META,$v); $n++; } } $r['atstatyta_meta']=$n; $r['nuimta_terminu']=$t; $trans(); if(function_exists('wp_cache_clear_cache')) wp_cache_clear_cache(); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
}, 1);
